{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table maplemonk.nr_target_vs_actual_daily as With Actuals as ( select month_date, PRODUCT_NAME, Channel, marketplace, sum(ifnull(Actual_Numerator,0)) as Actual_Numerator, sum(ifnull(Actual_Denominator,0)) as Actual_Denominator, sum(ifnull(tertiary,0)) as Tertiary from ( ( select date(cast(ORDER_Date as timestamp)) as month_date ,PRODUCT_NAME_final as product_name ,case when lower(marketplace) like \'%b2b%\' then \'B2B\' else \'ONLINE\' end as Channel ,marketplace ,sum((ifnull(selling_price,0) - ifnull(selling_price*18/118 ,0)) * 0.975)/100000 as Actual_Numerator ,NULL AS Actual_Denominator ,null as tertiary from Maplemonk.prolicious_wh_sales_consolidated where (lower(shipping_status) = \'delivered\' or lower(order_Status) = \'delivered\' or lower(FINAL_SHIPPING_STATUS) = \'delivered\') and not(upper(marketplace) like \'%b2b%\') group by 1,2,3,4 ) union all ( select date(cast(ORDER_Date as timestamp)) as month_date ,PRODUCT_NAME_final as product_name ,upper(marketplace) as Channel ,coalesce(Primary_Channel,\'OTHER\') marketplace ,null as Actual_Numerator ,NULL AS Actual_Denominator ,sum((ifnull(selling_price,0)))/100000 as tertiary from Maplemonk.prolicious_wh_sales_consolidated s left join ( select replace(upper(B2B_Customer_Names),\' \',\'\') as Customer_Name, upper(Mapped_Primary_Sales_Channel) as Primary_Channel from Maplemonk.Prolicious_Primary_Sales_Customer_Name_Mapping qualify row_number() over(partition by replace(upper(B2B_Customer_Names),\' \',\'\') order by 1 desc) = 1 )ps on replace(upper(s.name),\' \',\'\') = replace(upper(ps.Customer_Name),\' \',\'\') where (lower(marketplace) like \'%b2b%\') group by 1,2,3,4 )) group by 1,2,3,4 ), Targets as ( with monthly_targets AS ( SELECT PARSE_DATE(\'%m/%d/%Y\', month) as month_start, last_day(PARSE_DATE(\'%m/%d/%Y\', month)) AS month_end, UPPER(channel) AS channel, UPPER(marketplace) AS marketplace, SAFE_CAST(Target__in_INR_ AS FLOAT64)/100000 AS target_value FROM maplemonk.Prolicious_targets WHERE Target__in_INR_ IS NOT NULL ), day_generator AS ( SELECT day_offset FROM UNNEST(GENERATE_ARRAY(0, 32)) AS day_offset ), expanded_days AS ( SELECT mt.month_start, mt.month_end, mt.channel, mt.marketplace, mt.target_value, DATE_ADD(mt.month_start, INTERVAL dg.day_offset DAY) AS day_date, EXTRACT(DAY FROM mt.month_end) AS num_days_in_month FROM monthly_targets mt JOIN day_generator dg ON DATE_ADD(mt.month_start, INTERVAL dg.day_offset DAY) <= mt.month_end ) SELECT day_date AS month, channel, marketplace, target_value / num_days_in_month AS Target_Numerator, NULL AS Target_Denominator FROM expanded_days t ) select a.month_date as month_date, DATE(COALESCE(a.month_date, t.month)) as Month, a.PRODUCT_NAME, upper(COALESCE(a.channel,t.channel)) as Channel, upper(COALESCE(a.marketplace, t.marketplace)) AS marketplace, a.Actual_Numerator AS Actual_Numerator, a.Actual_Denominator AS Actual_Denominator, a.tertiary as tertiary, safe_divide(COALESCE(t.Target_Numerator, 0),COUNT(*) OVER (PARTITION BY COALESCE(a.month_date, t.month), COALESCE(LOWER(a.marketplace), LOWER(t.marketplace)), COALESCE(LOWER(a.channel), LOWER(t.channel)) )) AS Target_Numerator, t.Target_Denominator AS Target_Denominator FROM Actuals a FULL OUTER JOIN Targets t ON a.month_date = t.month AND lower(a.marketplace) = lower(t.marketplace) and lower(a.channel) = lower(t.channel) ; CREATE OR REPLACE TABLE MapleMonk.Prolocious_NR_DRR_Fact_items AS WITH RECURSIVE month_ends AS ( SELECT DATE_SUB(DATE_ADD(DATE_TRUNC(DATE \'2024-06-30\', MONTH), INTERVAL 1 MONTH), INTERVAL 1 DAY) AS DATE UNION ALL SELECT DATE_SUB(DATE_ADD(DATE_TRUNC(DATE_ADD(DATE, INTERVAL 1 MONTH), MONTH), INTERVAL 1 MONTH), INTERVAL 1 DAY) FROM month_ends WHERE DATE < CURRENT_DATE() ) , Month_Level_Data AS ( SELECT LAST_DAY(month) AS Date1, UPPER(IFNULL(PRODUCT_NAME, \'Others\')) AS PRODUCT_NAME, UPPER(COALESCE(CHANNEL, \'Others\')) AS CHANNEL, UPPER(marketplace) AS marketplace, SUM(IFNULL(ACTUAL_NUMERATOR, 0)) AS ACTUAL_NUMERATOR FROM maplemonk.nr_target_vs_actual_daily GROUP BY 1,2,3,4 ), combine AS ( SELECT * FROM month_ends CROSS JOIN Month_Level_Data ) SELECT c.*, Channel AS FINAL_MARKETPLACE, CASE WHEN LAST_DAY(Date1) = LAST_DAY(CURRENT_DATE()) THEN EXTRACT(DAY FROM month_date1) ELSE EXTRACT(DAY FROM LAST_DAY(Date1)) END AS drr_d, DATE_TRUNC(DATE, MONTH) AS Month_Start_Date FROM combine c LEFT JOIN ( SELECT UPPER(marketplace) AS final_marketplace, MAX(month) AS month_date1 FROM maplemonk.nr_target_vs_actual_daily WHERE month IS NOT NULL GROUP BY 1 ) l3 ON c.marketplace = l3.final_marketplace;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
